llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Meptazinol, a phenolic opioid analgesic with a tertiary amine, had a mean absolute oral bioavailability of 8.7 ± 1.6% in healthy male volunteers, demonstrating extensive first-pass metabolism in a close functional analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, a phenolic benzomorphan opioid, had a mean absolute oral bioavailability of about 18% in healthy subjects, below the 20% threshold and supporting low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Naloxegol, a PEGylated morphinan, showed about 90% oral bioavailability in a PBPK simulation; this is contradictory high-F evidence, but its PEGylation and 6-ether modification are not shared with the query and reduce mechanistic transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Codeine, a morphinan with a 3-methoxy group, had about 80.5% oral bioavailability in healthy subjects; this high-F evidence is contradictory but less applicable because the query has a free phenolic 3-OH subject to conjugative first-pass metabolism.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The highest-transfer analogues are phenolic opioids with measured absolute oral bioavailability below 20% (meptazinol ~8.7%, pentazocine ~18%), indicating substantial first-pass metabolism that is expected to apply to the query's phenolic morphinan scaffold. High-F analogues either lack the free phenol (codeine), are PEGylated (naloxegol), or are structurally unrelated, so they do not override the low-F evidence. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for oxymorphone itself is present in the supplied evidence.",
    "Contradictory high-F morphinan/opioid analogues have structural modifications that alter absorption or first-pass metabolism.",
    "Human oral bioavailability may be formulation- or dose-dependent, adding quantitative uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

